def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_prev_bids = []
    rich_opp_count = 0

    for oid, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive_opps.append(opp)
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_opp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 18.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    urgent_pressure = max(urgent_prev_bids) if urgent_prev_bids else high_pressure

    supply_tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_tightness < 0:
        supply_tightness = 0.0
    if supply_tightness > 1:
        supply_tightness = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.7
    elif hp <= 4:
        danger += 0.4
    if no_water >= 2:
        danger += 0.7
    elif no_water >= 1:
        danger += 0.35
    if day >= 8:
        danger += 0.15
    if danger > 1.0:
        danger = 1.0

    base = 18.0 + 24.0 * supply_tightness + 10.0 * min(rich_opp_count, 2)

    if danger >= 0.85:
        target = max(base + 35.0, urgent_pressure + 3.0, 62.0)
    elif danger >= 0.45:
        target = max(base + 18.0, urgent_pressure + 2.0, 42.0)
    else:
        if supply >= 22:
            target = max(12.0, min(base, high_pressure * 0.45 if high_pressure > 0 else 16.0))
        elif supply >= 19:
            target = max(20.0, min(base + 4.0, high_pressure * 0.7 if high_pressure > 0 else 26.0))
        else:
            target = max(base + 10.0, high_pressure + 1.5 if high_pressure > 0 else 34.0)

    if budget < DAILY_SALARY * 0.6 and danger < 0.45:
        target *= 0.82
    elif budget > DAILY_SALARY * 1.8 and (supply <= 18 or danger >= 0.45):
        target += 6.0

    if hp >= 8 and no_water == 0 and supply >= 23:
        target = min(target, 16.0)

    bid = min(float(budget), float(target))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, take a safe low bid.
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bid pressure from previous_trace only.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: lower supply means fewer units; bid more.
    # Expected number of allocations roughly scales with supply/WATER_REQ.
    alloc_factor = supply / float(WATER_REQ)  # float
    # Map alloc_factor to a pressure multiplier.
    if alloc_factor <= 1.1:
        pressure = 1.25
    elif alloc_factor <= 1.7:
        pressure = 1.10
    else:
        pressure = 0.95

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Base willingness: moderate. Prefer not to chase Cindy/David's high bids.
    base = DAILY_SALARY * 0.55

    # If my hp is critical or I've already been without water, increase.
    if hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * 0.90
    elif hp <= 4.0:
        base = DAILY_SALARY * 0.70

    # If yesterday someone paid extremely high, we may need to counter slightly,
    # but cap below matching their max to preserve budget.
    # Cindy/David showed ~90-130; Alex died with high bid too; Eric was low.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        # Bid enough to avoid being priced out, but not equal to their ceiling.
        target = min(DAILY_SALARY * 0.75, highest_prev_bid * 0.55 + DAILY_SALARY * 0.15)
    else:
        # If bids were not extreme, bid around base adjusted by pressure and avg.
        target = base
        if avg_prev_bid > 0:
            target = 0.65 * target + 0.35 * avg_prev_bid

    bid = float(target) * float(pressure)

    # Ensure bid is at least a small positive amount when competing.
    # Also never exceed budget.
    bid = max(1.0, bid)
    bid = min(bid, budget)

    # If budget is too low, spend what's left.
    if budget <= 1.0:
        return float(budget)

    # Gentle day-based adjustment to avoid running out too early (episode up to 10).
    # Later days: slightly more aggressive.
    if day >= 8:
        bid = min(budget, bid * 1.15)
    elif day <= 2:
        bid = max(1.0, bid * 0.95)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    bob = opponents_status.get('Bob', {})
    bob_prev_bid = 0
    if bob and 'previous_trace' in bob and bob['previous_trace']:
        bob_prev_bid = bob['previous_trace'].get('bid', 0)

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(bob_prev_bid + 2.0, DAILY_SALARY * 0.7))

    if bob.get('alive', False):
        return min(my_status['budget'], max(bob_prev_bid * 0.9, DAILY_SALARY * 0.4))

    return min(my_status['budget'], DAILY_SALARY * 0.35)
